counterexample:
INSERT INTO t1 (c1, c2) VALUES ('A', 'x');
INSERT INTO t1 (c1, c2) VALUES ('B', 'y');

INSERT INTO t2 (c1, c2) VALUES ('Amstel', 'bev');
INSERT INTO t2 (c1, c2) VALUES ('Corona', 'bev');

INSERT INTO t3 (c1, c2) VALUES ('Z', 't3val');

-- t5 rows: one qualifies Q1 via Amstel and c3>2; the other enables Q2 via Corona but c3<=2
INSERT INTO t5 (c1, c2, c3) VALUES ('A', 'Amstel', 3.00);
INSERT INTO t5 (c1, c2, c3) VALUES ('B', 'Corona', 1.00);

-- t4 links t3 'Z' to t1 'B'
INSERT INTO t4 (c1, c2, c3) VALUES ('Z', 'B', 1);

-- t6 shows t3 'Z' with a non-Corona t2 value
INSERT INTO t6 (c1, c2) VALUES ('Z', 'Amstel');

