counterexample:
INSERT INTO t1 (c1, c2) VALUES
  ('X', 'x');

INSERT INTO t2 (c1, c2) VALUES
  ('Corona', 'virus');

INSERT INTO t3 (c1, c2) VALUES
  ('A', 'alpha');

-- t4 row: c2='X' (references t1), c1='A' (references t3)
INSERT INTO t4 (c1, c2, c3) VALUES
  ('A', 'X', 1);

-- t5 row: c1='X' (matches t4.c2), c2='Corona' (triggers Q2 filter); note (c1,c2,c3) != t4's, so NATURAL JOIN finds no match
INSERT INTO t5 (c1, c2, c3) VALUES
  ('X', 'Corona', 9.99);

-- t6 left empty so NOT IN does not exclude 'A'

schema:
CREATE TABLE t1 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    PRIMARY KEY (c1)
);

CREATE TABLE t2 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    PRIMARY KEY (c1)
);

CREATE TABLE t3 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    PRIMARY KEY (c1)
);

CREATE TABLE t4 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    c3 SMALLINT NOT NULL,
    PRIMARY KEY (c1, c2),
    FOREIGN KEY (c1) REFERENCES t3(c1),
    FOREIGN KEY (c2) REFERENCES t1(c1)
);

CREATE TABLE t5 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    c3 DECIMAL(5,2) NOT NULL,
    PRIMARY KEY (c1, c2),
    FOREIGN KEY (c1) REFERENCES t1(c1),
    FOREIGN KEY (c2) REFERENCES t2(c1)
);

CREATE TABLE t6 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    PRIMARY KEY (c1, c2),
    FOREIGN KEY (c1) REFERENCES t3(c1),
    FOREIGN KEY (c2) REFERENCES t2(c1)
);

counterexample:
INSERT INTO t1 (c1, c2) VALUES ('A', 't1-A');
INSERT INTO t2 (c1, c2) VALUES ('Corona', 't2-Corona');
INSERT INTO t2 (c1, c2) VALUES ('Z', 't2-Z');
INSERT INTO t3 (c1, c2) VALUES ('T3a', 't3-a');

-- t4 references t3(c1) and t1(c1)
INSERT INTO t4 (c1, c2, c3) VALUES ('T3a', 'A', 1);

-- t5 references t1(c1) and t2(c1); note t5.c2 = 'Corona'
INSERT INTO t5 (c1, c2, c3) VALUES ('A', 'Corona', 1.00);

-- t6 references t3(c1) and t2(c1); note t6.c2 <> 'Corona'
INSERT INTO t6 (c1, c2) VALUES ('T3a', 'Z');

