counterexample:
INSERT INTO t1 (c1, c2) VALUES ('A', 'x');
INSERT INTO t1 (c1, c2) VALUES ('Corona', 'y');

INSERT INTO t2 (c1, c2) VALUES ('Corona', 'beer');

INSERT INTO t3 (c1, c2) VALUES ('A', 'z');

-- t4 has c3 = 2
INSERT INTO t4 (c1, c2, c3) VALUES ('A', 'Corona', 2);

-- t5 has c3 = 3.00 (does not match t4.c3), so NATURAL JOIN fails
INSERT INTO t5 (c1, c2, c3) VALUES ('A', 'Corona', 3.00);

schema:
CREATE TABLE t1 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    PRIMARY KEY (c1)
);

CREATE TABLE t2 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    PRIMARY KEY (c1)
);

CREATE TABLE t3 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    PRIMARY KEY (c1)
);

CREATE TABLE t4 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    c3 SMALLINT NOT NULL,
    PRIMARY KEY (c1, c2),
    FOREIGN KEY (c1) REFERENCES t3(c1),
    FOREIGN KEY (c2) REFERENCES t1(c1)
);

CREATE TABLE t5 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    c3 DECIMAL(5,2) NOT NULL,
    PRIMARY KEY (c1, c2),
    FOREIGN KEY (c1) REFERENCES t1(c1),
    FOREIGN KEY (c2) REFERENCES t2(c1)
);

CREATE TABLE t6 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    PRIMARY KEY (c1, c2),
    FOREIGN KEY (c1) REFERENCES t3(c1),
    FOREIGN KEY (c2) REFERENCES t2(c1)
);

counterexample:
INSERT INTO t1 (c1, c2) VALUES
  ('Corona', 't1-val'),
  ('A', 't1-A'),
  ('B', 't1-B');

INSERT INTO t2 (c1, c2) VALUES
  ('Corona', 't2-val');

INSERT INTO t3 (c1, c2) VALUES
  ('A', 't3-A'),
  ('B', 't3-B');

-- Rows that will join (NATURAL JOIN on c1, c2, c3)
INSERT INTO t4 (c1, c2, c3) VALUES
  ('A', 'Corona', 1),
  ('B', 'Corona', 2);

INSERT INTO t5 (c1, c2, c3) VALUES
  ('A', 'Corona', 1.00),
  ('B', 'Corona', 2.00);

-- Make only 'B' present in t6 for c2='Corona'
INSERT INTO t6 (c1, c2) VALUES
  ('B', 'Corona');

