    c2 VARCHAR NOT NULL,
    c3 SMALLINT NOT NULL,
    PRIMARY KEY (c1, c2),
    FOREIGN KEY (c1) REFERENCES t3(c1),
    FOREIGN KEY (c2) REFERENCES t1(c1)
);

CREATE TABLE t5 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    c3 DECIMAL(5,2) NOT NULL,
    PRIMARY KEY (c1, c2),
    FOREIGN KEY (c1) REFERENCES t1(c1),
    FOREIGN KEY (c2) REFERENCES t2(c1)
);

CREATE TABLE t6 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    PRIMARY KEY (c1, c2),
    FOREIGN KEY (c1) REFERENCES t3(c1),
    FOREIGN KEY (c2) REFERENCES t2(c1)
);

counterexample:
INSERT INTO t1 (c1, c2) VALUES ('A', 'a2');
INSERT INTO t1 (c1, c2) VALUES ('B', 'b2');

INSERT INTO t2 (c1, c2) VALUES ('Y1', 'y1_2');
INSERT INTO t2 (c1, c2) VALUES ('Y2', 'y2_2');

INSERT INTO t3 (c1, c2) VALUES ('X', 'x2');

-- t4 links X to A
INSERT INTO t4 (c1, c2, c3) VALUES ('X', 'A', 1);

-- t5 has an offending row for A with c2 = Y1 (not covered by t6 for X)
INSERT INTO t5 (c1, c2, c3) VALUES ('A', 'Y1', 1.00);
-- and another t5 row with c2 = Y2 (will match t6 on c2, enabling Q2)
INSERT INTO t5 (c1, c2, c3) VALUES ('B', 'Y2', 2.00);

-- t6 has only Y2 for X (does NOT include Y1)
INSERT INTO t6 (c1, c2) VALUES ('X', 'Y2');

